[data-slot="field"][data-layout="inline"] { grid-template-columns:minmax(120px,.8fr) minmax(0,1.4fr); gap:8px 24px; align-items:start; }
[data-slot="field"][data-layout="inline"] > [data-slot="field-label"] { grid-column:1; grid-row:1; padding-top:12px; }
